51	export function resolveBaseUrl(options: ResolveBaseUrlOptions = {}): string {
52	  const { request, fallback = 'http://localhost:8787' } = options;
53	
54	  // Helper to read a header from either a Request or a Hono-style accessor.
55	  const getHeader = (name: string): string | undefined => {
56	    if (options.header) return options.header(name);
